"A GitHub user or organization: every project of it is listed.": "एक GitHub उपयोगकर्ता या संगठन: उसके सभी प्रोजेक्ट सूचीबद्ध होते हैं।",
"A Model Context Protocol server gives a coding agent extra tools: files, the web, a browser, GitHub and the like. This only reaches the agents that sign in through their own command-line tool in Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode) — an agent used only with an API key cannot use one here.": "Model Context Protocol सर्वर कोडिंग एजेंट को अतिरिक्त टूल देता है: फ़ाइलें, वेब, ब्राउज़र, GitHub वगैरह। यह सिर्फ़ उन एजेंट तक पहुंचता है जो Termux में अपने कमांड-लाइन टूल से साइन इन करते हैं (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode) — सिर्फ़ API कुंजी से चलने वाला एजेंट यहां इसका इस्तेमाल नहीं कर सकता।",
