"A patch could not be applied. This usually means the patch does not fit this version of the app. Check the details below and the log.": "कोई पैच लागू नहीं हो सका। इसका आमतौर पर मतलब होता है कि पैच ऐप के इस संस्करण से मेल नहीं खाता। नीचे दिया ब्योरा और लॉग देखें।",
