"After a successful install, ask whether to delete the installer file (it goes to a hidden folder first, with an Undo)": "सफल इंस्टॉल के बाद पूछें कि इंस्टॉलर फ़ाइल हटानी है या नहीं (वह पहले छिपे फ़ोल्डर में जाती है, पूर्ववत करने के विकल्प के साथ)",
"Agent websites": "एजेंट की वेबसाइटें",
"Agent when the app opens": "ऐप खुलने पर एजेंट",
"Agents act through four kinds of steps: run a command, read a file, write a file, or edit part of a file. Before a command runs or a file changes you see exactly what, and choose Run (or Apply), Skip, or Always allow for the rest of the chat. Reading files in the current folder needs no OK.": "एजेंट चार तरह के चरणों से काम करते हैं: कमांड चलाना, फ़ाइल पढ़ना, फ़ाइल लिखना, या फ़ाइल का कुछ हिस्सा संपादित करना। कोई कमांड चलने या फ़ाइल बदलने से पहले आप ठीक-ठीक देखते हैं कि क्या होगा, और “चलाएं” (या “लागू करें”), “छोड़ें” या बाकी चैट के लिए “हमेशा अनुमति दें” चुनते हैं। मौजूदा फ़ोल्डर की फ़ाइलें पढ़ने के लिए मंज़ूरी नहीं चाहिए।",
"Agents can be wrong. Read what they want to run, especially with Working mode or Root, where a command can remove apps or change settings.": "एजेंट गलत भी हो सकते हैं। वे जो चलाना चाहते हैं उसे पढ़ें, खासकर वर्किंग मोड या Root के साथ, जहां एक कमांड ऐप्स हटा सकती है या सेटिंग बदल सकती है।",
"Agents only see what you send and what their steps return; keys and tokens in output are hidden from them.": "एजेंट सिर्फ़ वही देखते हैं जो आप भेजते हैं और जो उनके चरण लौटाते हैं; आउटपुट में मौजूद कुंजियां और टोकन उनसे छिपाए जाते हैं।",
