"Allows inspecting all installed applications, package names, activities, and permissions safely without modifying packages.": "सभी इंस्टॉल किए गए ऐप्स, पैकेज नाम, ऐक्टिविटी और अनुमतियों को पैकेज में बदलाव किए बिना सुरक्षित रूप से जांचने की सुविधा देता है।",
"Almost grey, with only a trace of your color.": "लगभग ग्रे, आपके रंग की बस हल्की झलक के साथ।",
