"Also show only (combine as many as you like):": "इनमें से भी सिर्फ़ ये दिखाएं (जितने चाहें मिलाएं):",
"Also sources ~/.bashrc, so aliases and functions from your own Termux shell work here too. Turn off if yours does something unexpected for a non-interactive shell.": "~/.bashrc को भी source करता है, इसलिए आपके अपने Termux शेल के alias और फ़ंक्शन यहां भी काम करते हैं। अगर वह नॉन-इंटरैक्टिव शेल में कुछ अनपेक्षित करे तो बंद कर दें।",
"Also target APK files that match the installed version. Disable to only remove older versions.": "इंस्टॉल किए संस्करण से मेल खाने वाली APK फ़ाइलों को भी शामिल करें। केवल पुराने संस्करण हटाने के लिए बंद करें।",
