"An F-Droid style repository": "F-Droid शैली की रिपॉज़िटरी",
"An app exclusion keeps one app out of the tools you pick (AppCleaner leaves its data alone, CorpseFinder does not call its folders remnants).": "ऐप अपवाद किसी एक ऐप को आपके चुने औज़ारों से बाहर रखता है (AppCleaner उसके डेटा को नहीं छेड़ता, CorpseFinder उसके फ़ोल्डरों को अवशेष नहीं मानता)।",
"An app row": "ऐप की पंक्ति",
"An app's icon": "ऐप का आइकन",
"An area for the system to drop log files into.": "वह क्षेत्र जहाँ सिस्टम लॉग फ़ाइलें रखता है।",
"An excluded file, folder or app is skipped by the tools you choose, and nothing in an excluded folder is deleted. Exclude from a scan result with the Exclude button of a row.": "बाहर रखी गई फ़ाइल, फ़ोल्डर या ऐप आपके चुने औज़ार छोड़ देते हैं, और बाहर रखे फ़ोल्डर में कुछ भी नहीं मिटाया जाता। स्कैन परिणाम से, पंक्ति के बाहर रखें बटन से बाहर रखें।",
"An install is already running": "एक इंस्टॉल पहले से चल रहा है",
"An overlay row": "ओवरले की पंक्ति",
