"App-specific": "ऐप-विशिष्ट",
"App: ADB Application Manager Pro ? (build ?)": "ऐप: ADB Application Manager Pro ? (बिल्ड ?)",
"AppCleaner can clear the caches that no file access can reach (the \"Clear cache\" button of an app's Storage screen) by tapping through the system settings for you. For that it needs this app's accessibility service. The service only acts while AppCleaner is clearing caches: it opens the App info screen of one app after the other, taps Clear cache, and stops when the screen turns off or locks. A cover over the screen shows what it is doing, with a way to cancel. Nothing is read or sent anywhere. On Android 13 and newer, an app installed from a file may first need \"Allow restricted settings\" (App info of this app, the three dots menu).": "AppCleaner वे कैश साफ़ कर सकता है जहाँ कोई फ़ाइल एक्सेस नहीं पहुँचता (किसी ऐप की स्टोरेज स्क्रीन का “कैश साफ़ करें” बटन), आपकी जगह सिस्टम सेटिंग में टैप करके। इसके लिए उसे इस ऐप की एक्सेसिबिलिटी सेवा चाहिए। सेवा केवल तब काम करती है जब AppCleaner कैश साफ़ कर रहा हो: वह एक-एक करके ऐप की ऐप जानकारी स्क्रीन खोलती है, कैश साफ़ करें पर टैप करती है, और स्क्रीन बंद या लॉक होने पर रुक जाती है। स्क्रीन पर एक परत दिखाती है कि वह क्या कर रही है, रद्द करने के रास्ते के साथ। कुछ भी पढ़ा या कहीं भेजा नहीं जाता। Android 13 और नए में, फ़ाइल से इंस्टॉल किए ऐप को पहले “प्रतिबंधित सेटिंग की अनुमति दें” चाहिए हो सकता है (इस ऐप की ऐप जानकारी, तीन बिंदु वाला मेनू)।",
