"Apps patched from now on are signed with the new key. Android will not install them over an app that was signed with the old key; export the old one first if you may need it.": "अब से पैच किए ऐप नई कुंजी से साइन होंगे। Android उन्हें पुरानी कुंजी से साइन ऐप के ऊपर इंस्टॉल नहीं करेगा; अगर पुरानी की ज़रूरत पड़ सकती है तो पहले उसे निर्यात करें।",
