"Aurora Store": "Aurora Store",
"Aurora Store is an open-source Play Store client. Automatic Play version detection is a planned follow-up (it needs anonymous Play authentication); for now this routes each app to its store page, opening Aurora Store when it's installed.": "Aurora Store एक ओपन-सोर्स Play Store क्लाइंट है। Play वर्शन का अपने-आप पता लगाना आगे की योजना में है (इसके लिए अनाम Play ऑथेंटिकेशन चाहिए); फ़िलहाल यह हर ऐप को उसके स्टोर पेज पर ले जाता है, और Aurora Store इंस्टॉल हो तो उसी में खोलता है।",
"Aurora Store: installed · Play Store: installed. Tap an app below to open its store page.": "Aurora Store: इंस्टॉल है · Play Store: इंस्टॉल है। किसी ऐप का स्टोर पेज खोलने के लिए नीचे उस पर टैप करें।",
"Aurora Store: installed · Play Store: not installed. Tap an app below to open its store page.": "Aurora Store: इंस्टॉल है · Play Store: इंस्टॉल नहीं है। किसी ऐप का स्टोर पेज खोलने के लिए नीचे उस पर टैप करें।",
"Aurora Store: not installed · Play Store: installed. Tap an app below to open its store page.": "Aurora Store: इंस्टॉल नहीं है · Play Store: इंस्टॉल है। किसी ऐप का स्टोर पेज खोलने के लिए नीचे उस पर टैप करें।",
