"Browser Use finished without an answer.": "Browser Use बिना उत्तर के समाप्त हो गया।",
"Browser Use is the open-source browser agent; this is its hosted cloud, which has a free tier for new accounts. An Ask agent button starts a short browser task that looks the question up on the web: it can take a minute or two and uses a little credit. It is for the Ask agent buttons only, not a chat. Testing the key costs nothing.": "Browser Use ओपन-सोर्स ब्राउज़र एजेंट है; यह उसका होस्टेड क्लाउड है, जिसमें नए खातों के लिए मुफ़्त स्तर है। Ask agent बटन एक छोटा ब्राउज़र कार्य शुरू करता है जो प्रश्न को वेब पर खोजता है: इसमें एक-दो मिनट लग सकते हैं और थोड़ा क्रेडिट लगता है। यह केवल Ask agent बटनों के लिए है, चैट के लिए नहीं। कुंजी की जाँच में कुछ खर्च नहीं होता।",
"Browser Use took too long (over 4 minutes). Try again later.": "Browser Use में बहुत देर लगी (4 मिनट से ज़्यादा)। बाद में फिर कोशिश करें।",
"Browser Use was stopped before it had an answer.": "Browser Use को उत्तर मिलने से पहले रोक दिया गया।",
