"Choose backup file…": "बैकअप फ़ाइल चुनें…",
"Choose folder": "फ़ोल्डर चुनें",
"Choose folder…": "फ़ोल्डर चुनें…",
"Choose package files": "पैकेज फ़ाइलें चुनें",
"Choose something to send first": "पहले भेजने के लिए कुछ चुनें",
"Choose the APK to patch first": "पहले पैच करने वाला APK चुनें",
"Choose the ones to send to the device": "डिवाइस पर भेजने के लिए चुनें",
"Choose the sign-in method in the agent's Connect sheet. The tools are installed into a Debian environment inside Termux when they have no Android build. This takes several minutes and up to about 1 GB; the providers do not support Android officially, so a tool may not run on every phone.": "साइन-इन का तरीका एजेंट की कनेक्ट शीट में चुनें। जिन टूल का कोई Android बिल्ड नहीं है, वे Termux के अंदर एक Debian एनवायरनमेंट में इंस्टॉल किए जाते हैं। इसमें कई मिनट और लगभग 1 GB तक लगते हैं; प्रोवाइडर आधिकारिक तौर पर Android को सपोर्ट नहीं करते, इसलिए हो सकता है कोई टूल हर फ़ोन पर न चले।",
"Choose the version and tap its download button. The file is saved here and the browser closes by itself.": "वर्शन चुनें और उसका डाउनलोड बटन दबाएँ। फ़ाइल यहाँ सहेजी जाती है और ब्राउज़र अपने आप बंद हो जाता है।",
"Choose what the extra button on each row of the Apps list does. It is always an icon, and the ones that change with the app (Enable / Disable, Install / Uninstall, Unsuspend / Suspend) switch their icon and action to match the app's current state.": "चुनें कि ऐप्स सूची की हर पंक्ति का अतिरिक्त बटन क्या करे। वह हमेशा एक आइकन होता है, और जो ऐप के हिसाब से बदलते हैं (सक्षम / अक्षम करें, इंस्टॉल / अनइंस्टॉल, अनसस्पेंड / सस्पेंड) वे ऐप की मौजूदा स्थिति के अनुसार अपना आइकन और कार्रवाई बदल लेते हैं।",
"Choose what to install and which starter files to write": "चुनें क्या इंस्टॉल करना है और कौन सी शुरुआती फ़ाइलें लिखनी हैं",
"Choosing a folder needs the app build": "फ़ोल्डर चुनने के लिए app बिल्ड चाहिए",
"Choosing files works in the app": "फ़ाइलें चुनना ऐप में काम करता है",
"Chosen:": "चुना गया:",
"Classic three-button navigation bar": "क्लासिक तीन-बटन नेविगेशन बार",
"Claude": "Claude",
"Claude (Anthropic)": "Claude (Anthropic)",
"Claude Code": "Claude Code",
"Claude Pro or Max and a Google account login may only be used in the providers' own apps: Anthropic and Google do not allow other apps to use those logins. So the Terminal signs you in through the official command-line tools running in Termux, where the provider's own website login opens:": "Claude Pro या Max और Google खाते का साइन-इन सिर्फ़ प्रोवाइडर के अपने ऐप्स में इस्तेमाल किया जा सकता है: Anthropic और Google दूसरे ऐप्स को इनका इस्तेमाल करने की अनुमति नहीं देते। इसलिए टर्मिनल आपको Termux में चलने वाले आधिकारिक कमांड-लाइन टूल के ज़रिए साइन इन कराता है, जहां प्रोवाइडर की अपनी वेबसाइट का साइन-इन खुलता है:",
"Clean up what is not needed any more: superfluous files, the expendable data of apps, the leftovers of apps that are gone, and files that exist twice. Scan first, look at the list, take out what you want to keep, then delete. The four tools use the working mode of this app for the folders a normal app cannot read.": "जो अब ज़रूरी नहीं उसे साफ़ करें: फ़ालतू फ़ाइलें, ऐप का छोड़ने लायक डेटा, हट चुके ऐप के अवशेष, और दो बार मौजूद फ़ाइलें। पहले स्कैन करें, सूची देखें, जो रखना है उसे निकालें, फिर मिटाएँ। चारों औज़ार उन फ़ोल्डरों के लिए इस ऐप का वर्किंग मोड इस्तेमाल करते हैं जिन्हें सामान्य ऐप नहीं पढ़ सकता।",
"Clean — no engine flagged this file": "साफ़ — किसी इंजन ने इस फ़ाइल को चिह्नित नहीं किया",
"Cleanup is simulated. Files are scanned and reported, but nothing is actually deleted.": "सफ़ाई केवल नकली है। फ़ाइलें स्कैन होकर रिपोर्ट होती हैं, पर असल में कुछ नहीं मिटता।",
