"Commands run as Termux, in its home folder, with your Termux packages and (with Match my Termux environment on) your aliases and functions too. Sync with Termux also opens Termux so you can grant it access to shared storage.": "कमांड Termux के रूप में, उसके होम फ़ोल्डर में, आपके Termux पैकेज के साथ चलती हैं और (मेरे Termux एनवायरनमेंट से मिलाएं चालू होने पर) आपके alias और फ़ंक्शन के साथ भी। Termux से सिंक करें Termux को भी खोलता है, ताकि आप उसे शेयर्ड स्टोरेज का एक्सेस दे सकें।",
