"Copilot needs a Copilot plan. GitHub retired GitHub Models in July 2026, so the Terminal uses GitHub's official Copilot CLI in Termux. Sign in there with GitHub, or save a fine-grained token with the \"Copilot Requests\" permission here and the CLI uses it.": "Copilot के लिए Copilot प्लान चाहिए। GitHub ने जुलाई 2026 में GitHub Models बंद कर दिया, इसलिए टर्मिनल Termux में GitHub का आधिकारिक Copilot CLI इस्तेमाल करता है। वहां GitHub से साइन इन करें, या यहां “Copilot Requests” अनुमति वाला fine-grained टोकन सहेजें, तो CLI उसे इस्तेमाल करेगा।",
