"Crawl4AI": "Crawl4AI",
"Crawl4AI found no answer for this one. Try Web search, or another agent.": "Crawl4AI को इसका उत्तर नहीं मिला। वेब खोज या कोई दूसरा एजेंट आज़माएँ।",
"Crawl4AI is the open-source web crawler; this is its hosted cloud. A new account gets free credits and a free monthly allowance, no card. An Ask agent button sends the question to its answer service, which searches the web, reads the pages and writes the answer. It is for the Ask agent buttons only, not a chat. The test spends one credit.": "Crawl4AI ओपन-सोर्स वेब क्रॉलर है; यह उसका होस्टेड क्लाउड है। नए खाते को मुफ़्त क्रेडिट और मुफ़्त मासिक कोटा मिलता है, कार्ड के बिना। Ask agent बटन प्रश्न को उसकी उत्तर सेवा को भेजता है, जो वेब खोजती है, पन्ने पढ़ती है और उत्तर लिखती है। यह केवल Ask agent बटनों के लिए है, चैट के लिए नहीं। जाँच में एक क्रेडिट खर्च होता है।",
