"Draw the app icons in the list with an icon pack you have installed (ADW, Nova, Apex and Go packs). Apps the pack does not cover get the pack's background and shape when it has one, and otherwise keep their own icon.": "सूची में ऐप आइकन आपके इंस्टॉल किए आइकन पैक से बनाएं (ADW, Nova, Apex और Go पैक)। जिन ऐप्स को पैक कवर नहीं करता, उन्हें पैक का बैकग्राउंड और आकार मिलता है अगर पैक में हो, वरना वे अपना आइकन रखते हैं।",
"Droid-ify": "Droid-ify",
"DroidMind": "DroidMind",
"DroidMind is an MCP server: a tool that gives AI agents control of an Android device over ADB (apps, files, logs, screenshots). It is not a chat by itself.": "DroidMind एक MCP सर्वर है: एक टूल जो AI एजेंटों को ADB के ज़रिए किसी Android डिवाइस का नियंत्रण देता है (ऐप्स, फ़ाइलें, लॉग, स्क्रीनशॉट)। यह अपने आप में कोई चैट नहीं है।",
"DroidMind is installed in Debian. Start it with: proot-distro login debian -- ~/.local/bin/droidmind --transport sse. Add it to your agent as an MCP server (its address is printed when it starts).": "DroidMind Debian में इंस्टॉल हो गया है। इसे इस कमांड से शुरू करें: proot-distro login debian -- ~/.local/bin/droidmind --transport sse। इसे अपने एजेंट में MCP सर्वर के रूप में जोड़ें (शुरू होने पर इसका पता छपता है)।",
