"EXPERT": "विशेषज्ञ",
"Each agent keeps this in its own file, the same way its official sign-in does, so two or more agents can carry the same server and either can be used with it. Codex keeps a remote server's token as an environment variable instead of in its file. Not tested against every version of every tool.": "हर एजेंट इसे अपनी ही फ़ाइल में रखता है, ठीक वैसे ही जैसे उसका आधिकारिक साइन-इन रखता है, इसलिए दो या ज़्यादा एजेंट एक ही सर्वर रख सकते हैं और दोनों उसके साथ इस्तेमाल हो सकते हैं। Codex रिमोट सर्वर का टोकन अपनी फ़ाइल की जगह एनवायरनमेंट वैरिएबल में रखता है। हर टूल के हर वर्शन पर इसकी जांच नहीं की गई है।",
"Each shell keeps its own screen and stays open while you use other tabs: cd, export and variables carry over from one command to the next. Restart shell starts a fresh one.": "हर शेल की अपनी स्क्रीन होती है और दूसरे टैब इस्तेमाल करते समय भी शेल खुला रहता है: cd, export और वेरिएबल एक कमांड से अगली तक बने रहते हैं। शेल रीस्टार्ट करें से नया शेल शुरू होता है।",
"Each wait is 600 seconds (10 minutes) at most.": "हर प्रतीक्षा अधिकतम 600 सेकंड (10 मिनट) की है।",
"Earlier certificates (the signing key was changed)": "पहले के सर्टिफ़िकेट (साइनिंग कुंजी बदली गई थी)",
