"Edit saved command": "सहेजी गई कमांड संपादित करें",
"Edit text": "टेक्स्ट संपादित करें",
"Edited": "बदली गई",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again: use Sign (this app signs with a key of its own).": "APK को संपादित करने से उसकी सामग्री बदल जाती है, इसलिए उसका सिग्नेचर अब मेल नहीं खाता। फिर से साइन किए बिना Android इसे इंस्टॉल नहीं करेगा: साइन करें दबाएं (यह ऐप अपनी एक कुंजी से साइन करता है)।",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again; Sign does that with a key of this app.": "APK को संपादित करने से उसकी सामग्री बदल जाती है, इसलिए उसका सिग्नेचर अब मेल नहीं खाता। फिर से साइन किए जाने तक Android इसे इंस्टॉल नहीं करेगा; साइन करें यह काम इस ऐप की कुंजी से करता है।",
"Effort": "प्रयास",
"Effort only changes anything for the agents whose own API has that knob (Claude, ChatGPT, Gemini, Grok); for the others it is kept but has no effect when chatting by API key, and none of them pass it on to their own sign-in tool in Termux.": "प्रयास सिर्फ़ उन एजेंट पर असर डालता है जिनके अपने API में यह सेटिंग है (Claude, ChatGPT, Gemini, Grok); बाकी के लिए यह सहेजा रहता है, पर API कुंजी से चैट करते समय इसका कोई असर नहीं होता, और उनमें से कोई भी इसे Termux में अपने साइन-इन टूल को नहीं भेजता।",
