"Found by reading the class names in the app's code on this phone; nothing is sent anywhere. Tracker list: Exodus Privacy, licensed ODbL 1.0. Code renamed by a shrinker (R8, ProGuard) or loaded later can hide a tracker, so a low number is not proof that there are none.": "इस फ़ोन पर ऐप के कोड में क्लास के नाम पढ़कर मिला; कुछ भी कहीं नहीं भेजा जाता। ट्रैकर सूची: Exodus Privacy, ODbL 1.0 लाइसेंस। श्रिंकर (R8, ProGuard) से नाम बदला या बाद में लोड हुआ कोड ट्रैकर छिपा सकता है, इसलिए कम संख्या इस बात का प्रमाण नहीं कि कोई है ही नहीं।",
