"Freeze, debloat, install, back up and inspect every app on your phone, straight from the phone: through ADB, Wireless Debugging, Shizuku or Root. No computer, no account, no ads.": "अपने फ़ोन के हर ऐप को फ़्रीज़ करें, डीब्लोट करें, इंस्टॉल करें, बैकअप लें और जांचें — सीधे फ़ोन से, ADB, वायरलेस डीबगिंग, Shizuku या Root के ज़रिए। न कंप्यूटर, न खाता, न विज्ञापन।",
"From File Manager: installing through a privileged backend, with this app's signature checks off. Android still verifies signatures itself: an APK whose signature it can't verify is signed with this app's key and installed, and an app signed by someone else can only be replaced after uninstalling it (you are asked first).": "फ़ाइल मैनेजर से: विशेषाधिकार वाले बैकएंड के ज़रिए इंस्टॉल, इस ऐप की सिग्नेचर जांच बंद रखकर। Android फिर भी सिग्नेचर खुद सत्यापित करता है: जिस APK का सिग्नेचर वह सत्यापित नहीं कर पाता उसे इस ऐप की कुंजी से साइन करके इंस्टॉल किया जाता है, और किसी और के साइन किए ऐप को बदलने के लिए पहले उसे अनइंस्टॉल करना होगा (पहले आपसे पूछा जाता है)।",
