"Lenovo": "Lenovo",
"Leon is an open-source personal assistant (skills, voice) that runs on a computer with Node.js and Python. It has no Android version and is not a coding agent, so it does not chat in this Terminal.": "Leon एक ओपन-सोर्स पर्सनल असिस्टेंट (स्किल, आवाज़) है, जो Node.js और Python के साथ कंप्यूटर पर चलता है। इसका कोई Android वर्शन नहीं है और यह कोडिंग एजेंट नहीं है, इसलिए यह इस टर्मिनल में चैट नहीं करता।",
"Leon.ai": "Leon.ai",
"Let Termux take commands from other apps": "Termux को दूसरे ऐप्स से कमांड लेने दें",
"Let them act without asking": "उन्हें बिना पूछे काम करने दें",
"Lets the agent read and write files under the folder named at the end of the command (change /sdcard to taste).": "एजेंट को कमांड के अंत में दिए गए फ़ोल्डर के अंदर फ़ाइलें पढ़ने और लिखने देता है (/sdcard को अपनी पसंद से बदलें)।",
"Lets the agent think in explicit steps before it acts.": "एजेंट को कार्रवाई से पहले साफ़ चरणों में सोचने देता है।",
"Lets this app change a few protected system settings used by some advanced features.": "इस ऐप को कुछ संरक्षित सिस्टम सेटिंग बदलने देता है, जिन्हें कुछ उन्नत फ़ीचर इस्तेमाल करते हैं।",
"Lets this app install the package files you choose, such as APK, APKS and XAPK files from your storage.": "इस ऐप को आपके चुने हुए पैकेज फ़ाइलें इंस्टॉल करने देता है, जैसे आपके स्टोरेज की APK, APKS और XAPK फ़ाइलें।",
"Lets this app open another app's screen from the background, such as an app you have just installed.": "इस ऐप को बैकग्राउंड से किसी दूसरे ऐप की स्क्रीन खोलने देता है, जैसे अभी इंस्टॉल किया गया ऐप।",
"Level": "स्तर",
"Levels and descriptions come from the UAD-NG project (GPL-3.0). The list is downloaded from their GitHub and cached on this phone.": "स्तर और विवरण UAD-NG प्रोजेक्ट (GPL-3.0) से आते हैं। सूची उनके GitHub से डाउनलोड होती है और इस फ़ोन पर कैश की जाती है।",
"Levels and package data come from the UAD-NG project (GPL-3.0). The list is downloaded from their GitHub and cached on this phone.": "लेवल और पैकेज डेटा UAD-NG प्रोजेक्ट (GPL-3.0) से आता है। सूची उनके GitHub से डाउनलोड होकर इस फ़ोन पर कैश की जाती है।",
