"No account, no ads, no analytics and no server of ours. Everything runs on your phone. The app only goes online for something you open or ask for: update checks, App Stores, the debloat list, and a VirusTotal lookup if you add your own key.": "कोई खाता नहीं, कोई विज्ञापन नहीं, कोई एनालिटिक्स नहीं और हमारा कोई सर्वर नहीं। सब कुछ आपके फ़ोन पर चलता है। ऐप सिर्फ़ तभी ऑनलाइन जाता है जब आप कुछ खोलें या मांगें: अपडेट की जांच, ऐप स्टोर, डीब्लोट सूची, और अपनी कुंजी जोड़ने पर VirusTotal लुकअप।",
"No actions recorded yet. Debloater and batch actions appear here.": "अभी तक कोई कार्रवाई दर्ज नहीं हुई। डीब्लोटर और बैच कार्रवाइयां यहां दिखेंगी।",
