"OpenCode is an open-source coding agent. After installing it, sign in to a provider with opencode auth login: it supports a ChatGPT plan, GitHub Copilot and API keys of many providers.": "OpenCode एक ओपन-सोर्स कोडिंग एजेंट है। इसे इंस्टॉल करने के बाद opencode auth login से किसी प्रोवाइडर में साइन इन करें: यह ChatGPT प्लान, GitHub Copilot और कई प्रोवाइडर की API कुंजियों को सपोर्ट करता है।",
