"Pick a .mpp patch bundle from storage. A local source never updates on its own: pick the new file when one comes out.": "स्टोरेज से .mpp पैच बंडल चुनें। स्थानीय स्रोत अपने आप कभी अपडेट नहीं होता: नई फ़ाइल आने पर उसे चुनें।",
