"Pick an agent, then the model and the effort (Low, Balanced or High: how hard it is asked to think). The first time, both start at a balanced choice, and the agent asks for what it needs (an API key, a server address, or a sign-in) and tests it before you start.": "कोई एजेंट चुनें, फिर मॉडल और प्रयास (कम, संतुलित या उच्च: उससे कितना गहराई से सोचने को कहा जाए)। पहली बार दोनों संतुलित विकल्प पर शुरू होते हैं, और एजेंट अपनी ज़रूरत की चीज़ (API कुंजी, सर्वर पता या साइन-इन) मांगता है और आपके शुरू करने से पहले उसकी जांच करता है।",
