"Pick which split APKs to install. The base APK is always included, and every other split starts ticked because \"Select all splits by default\" is on.": "चुनें कि कौन-से स्प्लिट APK इंस्टॉल करने हैं। बेस APK हमेशा शामिल रहता है, और बाकी हर स्प्लिट पर पहले से निशान लगा है क्योंकि “सभी स्प्लिट डिफ़ॉल्ट रूप से चुनें” चालू है।",
"Pick which split APKs to install. The base APK is always included; the splits that fit this phone are ticked and the others are left off for you to add.": "चुनें कि कौन-से स्प्लिट APK इंस्टॉल करने हैं। बेस APK हमेशा शामिल रहता है; इस फ़ोन के लिए सही स्प्लिट पर निशान लगा है और बाकी आपके जोड़ने के लिए छोड़े गए हैं।",
