"Termux Cheat Sheet": "Termux चीट शीट",
"Termux answered": "Termux ने जवाब दिया",
"Termux answered. All set.": "Termux ने जवाब दिया। सब तैयार है।",
"Termux could not be opened. Is it installed?": "Termux नहीं खुल सका। क्या यह इंस्टॉल है?",
"Termux does not accept commands from other apps yet. In Termux, run:": "Termux अभी दूसरे ऐप्स से कमांड नहीं लेता। Termux में चलाएं:",
"Termux does not take commands from other apps yet: run the command of step 3 in Termux, then test again.": "Termux अभी दूसरे ऐप्स से कमांड नहीं लेता: Termux में चरण 3 की कमांड चलाएं, फिर दोबारा टेस्ट करें।",
"Termux is free. Get it from F-Droid or GitHub; the old Google Play build is not suitable.": "Termux मुफ़्त है। इसे F-Droid या GitHub से लें; Google Play वाला पुराना बिल्ड सही नहीं है।",
"Termux is not installed. It is free from F-Droid or GitHub.": "Termux इंस्टॉल नहीं है। यह F-Droid या GitHub से मुफ़्त मिलता है।",
"Termux is not set up for this app yet.": "Termux अभी इस ऐप के लिए सेट नहीं किया गया है।",
"Termux is ready: vim, nano, git and python are installed and bash has its starter .bashrc. Open the real terminal for full-screen programs.": "Termux तैयार है: vim, nano, git और python इंस्टॉल हैं और bash के पास अपना शुरुआती .bashrc है। फ़ुल-स्क्रीन प्रोग्राम के लिए असली टर्मिनल खोलें।",
"Termux permission": "Termux अनुमति",
"Termux setup": "Termux सेटअप",
"Termux shells read ~/.bash_profile or ~/.profile first (PATH and the like). Turn off if your profile starts another program.": "Termux शेल पहले ~/.bash_profile या ~/.profile पढ़ते हैं (PATH वगैरह)। अगर आपकी प्रोफ़ाइल कोई दूसरा प्रोग्राम शुरू करती है, तो इसे बंद करें।",
"Test": "टेस्ट करें",
"Test and save": "टेस्ट करके सहेजें",
"Test and save the token": "टोकन टेस्ट करके सहेजें",
"Test it in Settings": "सेटिंग में जाँचें",
"Test key": "कुंजी जाँचें",
"Test the Default Ask Agent": "डिफ़ॉल्ट Ask एजेंट जाँचें",
"Test the connection": "कनेक्शन टेस्ट करें",
"Testing the key…": "कुंजी जाँची जा रही है…",
"Testing…": "टेस्ट हो रहा है…",
"Text": "टेक्स्ट",
"Text copied": "टेक्स्ट कॉपी किया गया",
"Text editor": "टेक्स्ट एडिटर",
"Text size (1.0 = normal)": "टेक्स्ट का आकार (1.0 = सामान्य)",
"Text.": "टेक्स्ट।",
