"The text is identical (only the packing differs).": "टेक्स्ट एक जैसा है (सिर्फ़ पैकिंग अलग है)।",
"The text of this app. Names of apps, files and commands are not translated.": "इस ऐप का टेक्स्ट। ऐप्स, फ़ाइलों और कमांड के नाम अनुवादित नहीं किए जाते।",
"The theme was not changed": "थीम नहीं बदली गई",
"The three shells": "तीन शेल",
"The three tables": "तीन तालिकाएँ",
"The token works. The Copilot CLI uses it from now on.": "टोकन काम कर रहा है। अब से Copilot CLI इसे इस्तेमाल करेगा।",
"The two archives hold identical files.": "दोनों आर्काइव में एक जैसी फ़ाइलें हैं।",
