"Theme": "थीम",
"Theme applied": "थीम लागू की गई",
"Theme applied, but a switch would not change": "थीम लागू की गई, लेकिन एक स्विच नहीं बदला",
"Theme change refused": "थीम बदलने से मना किया गया",
