"When deleting duplicates, SD Maid decides which file to keep by checking each criterion in order. The first criterion that produces a clear winner determines the result. Drag to reorder, tap to change mode.": "डुप्लिकेट मिटाते समय SD Maid हर मानदंड को क्रम से जाँचकर तय करता है कि कौन सी फ़ाइल रखनी है। जो पहला मानदंड स्पष्ट विजेता देता है वही नतीजा तय करता है। क्रम बदलने के लिए खींचें, मोड बदलने के लिए टैप करें।",
"When the chosen source does not have the version or does not work, This version, Newest and All versions go on with the next source, in the order above, until one delivers.": "जब चुने स्रोत के पास संस्करण न हो या वह काम न करे, तो यह संस्करण, सबसे नया और सभी संस्करण ऊपर के क्रम में अगले स्रोत पर जाते हैं, जब तक कोई सफल न हो।",
