"You can grant or revoke it here.": "आप इसे यहां दे या वापस ले सकते हैं।",
"You edited this APK, so its signature is no longer valid and Android will not install it as it is.": "आपने इस APK को बदला है, इसलिए उसका सिग्नेचर अब मान्य नहीं है और Android इसे ऐसे ही इंस्टॉल नहीं करेगा।",
"You explain one Android hidden setting (an entry of the Settings.Global, Settings.Secure or Settings.System database, the ones \"settings get/put\" reads and writes) to someone who is not a developer.": "आप Android की एक छिपी सेटिंग (Settings.Global, Settings.Secure या Settings.System डेटाबेस की एक प्रविष्टि, जिन्हें “settings get/put” पढ़ता और लिखता है) किसी ऐसे व्यक्ति को समझा रहे हैं जो डेवलपर नहीं है।",
"You explain one Android hidden setting (an entry of the Settings.Global, Settings.Secure or Settings.System database, the ones \"settings get/put\" reads and writes) to someone who is not a developer. Say briefly: what it controls, what its values mean, what changing it does, and whether it is safe to change. Say plainly when you do not know the setting (many belong to the phone maker) instead of guessing, and then say what its name suggests. Short paragraphs, no headings.": "आप Android की एक छिपी सेटिंग (Settings.Global, Settings.Secure या Settings.System डेटाबेस की एक प्रविष्टि, जिन्हें “settings get/put” पढ़ता और लिखता है) किसी ऐसे व्यक्ति को समझा रहे हैं जो डेवलपर नहीं है। संक्षेप में बताएँ: यह क्या नियंत्रित करती है, इसके मान क्या दर्शाते हैं, बदलने से क्या होता है, और बदलना सुरक्षित है या नहीं। अगर आप सेटिंग नहीं जानते (कई फ़ोन निर्माता की होती हैं) तो अनुमान लगाने की जगह साफ़ कहें, फिर बताएँ कि उसका नाम क्या संकेत देता है। छोटे अनुच्छेद, कोई शीर्षक नहीं।",
"You explain one Android logcat entry to someone who is not a developer. Say, in plain words and briefly: what this line means,": "आप Android की एक logcat प्रविष्टि किसी ऐसे व्यक्ति को समझा रहे हैं जो डेवलपर नहीं है। सरल शब्दों में और संक्षेप में बताएँ: इस पंक्ति का क्या मतलब है,",
"You explain one Android logcat entry to someone who is not a developer. Say, in plain words and briefly: what this line means, the most likely cause, whether it matters (harmless noise, a real problem, or a crash) and, if it does matter, what to try. Use short paragraphs, no headings. If the line is too cryptic to explain with confidence, say so and say what else would help. Do not invent details.": "आप Android की एक logcat प्रविष्टि किसी ऐसे व्यक्ति को समझा रहे हैं जो डेवलपर नहीं है। सरल शब्दों में और संक्षेप में बताएँ: इस पंक्ति का क्या मतलब है, सबसे संभावित कारण, क्या यह मायने रखती है (बेअसर शोर, असली समस्या या क्रैश) और अगर मायने रखती है तो क्या आज़माएँ। छोटे अनुच्छेद इस्तेमाल करें, कोई शीर्षक नहीं। अगर पंक्ति इतनी गूढ़ है कि भरोसे से समझाई नहीं जा सकती, तो ऐसा कहें और बताएँ कि और क्या मदद करेगा। ब्योरे न गढ़ें।",
"You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically.": "आप Android टर्मिनल में ADB और शेल कमांड के सिंटैक्स में मदद करते हैं। संक्षेप में और व्यावहारिक जवाब दें।",
"You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically. If you want to propose exactly one command for the user to run here, put it by itself inside": "आप Android टर्मिनल में ADB और शेल कमांड के सिंटैक्स में मदद करते हैं। संक्षेप में और व्यावहारिक जवाब दें। अगर आप उपयोगकर्ता के चलाने के लिए यहां ठीक एक कमांड सुझाना चाहते हैं, तो उसे अकेले इसके अंदर रखें",
"You're on a metered connection (mobile data / hotspot).": "आप मीटर्ड कनेक्शन (मोबाइल डेटा / हॉटस्पॉट) पर हैं।",
